<!doctype html><html><head><meta charset="utf-8"><title>Visit Report</title><style>@page{size:A4 portrait;margin:8mm}*{box-sizing:border-box}body{margin:0;color:#102033;font-family:Arial,sans-serif;font-size:8px}.toolbar{margin:0 auto 10px;display:flex;justify-content:space-between}.toolbar button{padding:6px 12px;border:0;background:#159176;color:white}.sheet{border-top:2px solid #159176}.title{text-align:center}.title h1{margin:5px 0 3px;font-size:14px}.title p{margin:2px}.meta{display:grid;grid-template-columns:1.35fr 1.35fr 1fr;gap:8px;margin:10px 0 6px;padding:6px;border:1px solid #d5dbe0;background:#f8fafc;line-height:1.35}.summary-title{text-align:center;margin:10px 0 3px;font-size:9px}.summary-table{width:100%;border-collapse:collapse;font-size:7px}.summary-table th{background:#2784b8;color:#fff;text-align:left;padding:4px}.summary-table td{padding:3px;border-bottom:1px solid #ddd}.meta-primary{display:flex;gap:18px;flex-wrap:wrap}.table{width:100%;border-collapse:collapse;font-size:6.5px;table-layout:fixed}.table th,.table td{border:1px solid #d5dbe0;padding:3px 2px;text-align:left;vertical-align:top;overflow-wrap:anywhere}.table th{font-weight:bold;background:#fff}.table tr:nth-child(even) td{background:#f5f8fa}.table thead{display:table-header-group}.table tr{page-break-inside:avoid}.center{text-align:center!important}.right{text-align:right!important}.fee-list{margin:0;padding-left:12px}.muted{color:#718096}@media print{.toolbar{display:none}.sheet{border-top:2px solid #159176}.table th,.table tr:nth-child(even) td,.meta{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="toolbar"><strong>Visit Report</strong><button onclick="window.print()">Print / Save PDF</button></div><main class="sheet"><div class="title"><h1>Visit Report</h1><p><b>Date:</b> {{ \Carbon\Carbon::parse($fromDate)->format('d M Y') }} to {{ \Carbon\Carbon::parse($toDate)->format('d M Y') }}</p><p><b>Total Beneficiaries:</b> {{ $visits->pluck('app_customer_id')->unique()->count() }} | <b>Working Days:</b> {{ $workingDays }}</p></div><div class="meta"><div class="meta-primary"><span><b>Area Name:</b> {{ $warehouse->name }}</span><span><b>LSP:</b> {{ $salesmen->firstWhere('id', $salesmanId)?->name ?: 'All LSPs' }}</span></div><div><b>Group Number:</b> {{ $groupNumbers->implode(', ') ?: '-' }}</div><div><b>C.F:</b> {{ $visitTypeCounts['C.F']??0 }} &nbsp; <b>Re.V:</b> {{ $visitTypeCounts['Re.V']??0 }} &nbsp; <b>N.V:</b> {{ $visitTypeCounts['N.V']??0 }} &nbsp; <b>Reg.v:</b> {{ $visitTypeCounts['Reg.v']??0 }} &nbsp; <b>A.s:</b> {{ $visitTypeCounts['A.s']??0 }}</div></div><table class="table"><thead><tr><th style="width:3%">SL</th><th style="width:8%">Visit Nature</th><th style="width:12%">Beneficiary Name</th><th style="width:12%">Beneficiary Cell No.</th><th style="width:7%">Group Number</th><th style="width:9%">Beneficiary Number</th><th style="width:13%">Date</th><th style="width:11%">Memo/Invoice No(s)</th><th style="width:6%">File</th><th style="width:9%">Total Amount</th><th style="width:14%">Fee Types (itemized)</th></tr></thead><tbody>@forelse($visits as $visit)<tr><td>{{ $loop->iteration }}</td><td>{{ $visit->visit_type ?: '-' }}</td><td>{{ $visit->appCustomer?->name ?: '-' }}</td><td>{{ $visit->appCustomer?->mobile ?: ($visit->customer_number ?: 'No Number') }}</td><td>{{ $visit->appCustomer?->group_number ?: 'N/A' }}</td><td>{{ $visit->beneficiary_number ?: 'N/A' }}</td><td>{{ $visit->visit_date?->format('Y-m-d h:i A') }}</td><td>{{ is_array($visit->memo_no) && count($visit->memo_no) ? implode(', ', $visit->memo_no) : '--' }}</td><td>@if($visit->attachment_path)<a href="{{ asset(str_starts_with($visit->attachment_path, 'uploads/') ? $visit->attachment_path : 'storage/' . $visit->attachment_path) }}" target="_blank" rel="noopener" title="Open attachment" class="file-link">File</a>@else<span class="muted">N/A</span>@endif</td><td>{{ number_format($visit->fees->sum('amount'), 0) }} BDT</td><td>@if($visit->fees->isNotEmpty())<ul class="fee-list">@foreach($visit->fees as $fee)<li>{{ $fee->fee_type ?: '-' }}: {{ number_format($fee->amount, 0) }}</li>@endforeach</ul>@else<span class="muted">No fees</span>@endif</td></tr>@empty<tr><td colspan="10" class="center">No visits found.</td></tr>@endforelse</tbody></table><h3 class="summary-title">Summary</h3><table class="summary-table"><thead><tr><th>Fee Type</th><th>Daily Target</th><th>Total Target</th><th>Achieve Amount</th><th>Achievement %</th></tr></thead><tbody>@php($targets=["Deworming"=>400,"Fattening"=>900,"Medicine"=>1200,"Treatment and others"=>300])@foreach($targets as $type=>$daily)<tr><td>{{$type}}</td><td>{{number_format($daily)}} BDT</td><td>{{number_format($daily*$workingDays)}} BDT</td><td>{{number_format($feeSummary[$type]??0)}} BDT</td><td>{{number_format(($daily*$workingDays)>0?(($feeSummary[$type]??0)/($daily*$workingDays))*100:0,2)}}%</td></tr>@endforeach<tr><td><b>Grand Total</b></td><td></td><td>{{number_format(collect($targets)->sum()*$workingDays)}} BDT</td><td>{{number_format($feeSummary->sum())}} BDT</td><td>{{number_format(collect($targets)->sum()>0?($feeSummary->sum()/(collect($targets)->sum()*$workingDays))*100:0,2)}}%</td></tr></tbody></table></main></body></html>
